package com.zomiggy.entity;
import jakarta.persistence.*;
@Entity public class Coupon { @Id private String code; @Column(nullable=false) private String description; @Column(nullable=false) private int minimumSubtotal; @Column(nullable=false) private int discountType; @Column(nullable=false) private int discountValue; @Column(nullable=false) private int maximumDiscount; protected Coupon(){} public Coupon(String c,String d,int min,int type,int value,int max){code=c;description=d;minimumSubtotal=min;discountType=type;discountValue=value;maximumDiscount=max;} public String getCode(){return code;} public String getDescription(){return description;} public int discount(int subtotal){if(subtotal<minimumSubtotal)return 0; return discountType==0?discountValue:Math.min(subtotal*discountValue/100,maximumDiscount);} }